func() {
		if err := application.Run(); err != nil {
			log.Fatalf("application run error: %v", err)
		}
	}

func() {
		buf := make([]byte, 4096)
		stdout := termSession.Stdout()
		for {
			n, rErr := stdout.Read(buf)
			if n > 0 {
				if wErr := conn.Write(ctx, websocket.MessageText, buf[:n]); wErr != nil {
					errChan <- wErr
					return
				}
			}
			if rErr != nil {
				errChan <- rErr
				return
			}
		}
	}

func() {
		stdin := termSession.Stdin()
		for {
			_, msgBytes, rErr := conn.Read(ctx)
			if rErr != nil {
				errChan <- rErr
				return
			}

			var msg TerminalMessage
			if err := json.Unmarshal(msgBytes, &msg); err == nil {
				if msg.InputData != "" {
					_, _ = stdin.Write([]byte(msg.InputData))
				}
				if msg.Cols > 0 && msg.Rows > 0 {
					_ = termSession.Resize(msg.Cols, msg.Rows)
				}
			} else {
				_, _ = stdin.Write(msgBytes)
			}
		}
	}

func() {
			defer qrCancel()
			for evt := range qrChan {
				if evt.Event == "code" {
					c.qrMutex.Lock()
					c.qrCode = evt.Code
					if pngBytes, err := qrcode.Encode(evt.Code, qrcode.Medium, 256); err == nil {
						c.qrBase64 = "data:image/png;base64," + base64.StdEncoding.EncodeToString(pngBytes)
					}
					c.qrMutex.Unlock()

					if c.onStatus != nil {
						c.onStatus(c.SessionID, "needs_rescan", c.qrBase64, "", "")
					}
				} else {
					log.Printf("[WhatsApp Client %d] QR event: %s", c.SessionID, evt.Event)
				}
			}
		}
